import sys

def solve_nonogram(n, m, row_hints, col_hints):
    def backtrack(row, col, grid):
        if row == n:
            return True
        if col == m:
            return backtrack(row + 1, 0, grid)

        if grid[row][col] != '.':
            return backtrack(row, col + 1, grid)

        # Try placing a black cell
        can_place_black = True
        segment_length = 0
        for c in range(col, m):
            if grid[row][c] == '*':
                segment_length += 1
            elif grid[row][c] == '.':
                break
            else:
                can_place_black = False
                break

        if can_place_black and (segment_length < row_hints[row] or (segment_length == row_hints[row] and col + segment_length == m)):
            placed = False
            for c in range(col, m):
                if segment_length == row_hints[row] and grid[row][c] == '?':
                    grid[row][c] = '.'
                elif grid[row][c] == '?':
                    grid[row][c] = '*'
                    placed = True
                    segment_length += 1
                if segment_length == row_hints[row]:
                    break

            if placed and backtrack(row, col + 1, grid):
                return True

            for c in range(col, m):
                if grid[row][c] == '*':
                    grid[row][c] = '?'
                elif grid[row][c] == '.':
                    grid[row][c] = '?'
                    break

        # Try placing a white cell
        grid[row][col] = '.'
        if backtrack(row, col + 1, grid):
            return True

        grid[row][col] = '?'
        return False

    grid = [['?' for _ in range(m)] for _ in range(n)]
    backtrack(0, 0, grid)

    for r in range(n):
        for c in range(m):
            if grid[r][c] == '?':
                grid[r][c] = '.'

    return grid

def main():
    import sys
    input = sys.stdin.read().split()
    n, m = int(input[0]), int(input[1])
    row_hints = list(map(int, input[2:2+n]))
    col_hints = list(map(int, input[2+n:2+n+m]))

    grid = solve_nonogram(n, m, row_hints, col_hints)
    for row in grid:
        print(''.join(row))

main()
